contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(amount > 0);
        require(c.lrtConfig().isSupportedAsset(asset));
        uint256 limitBefore = c.getAssetCurrentLimit(asset);
        require(limitBefore > 0);

        bool zeroReverted;
        try c.depositAsset(asset, 0) { zeroReverted = false; } catch { zeroReverted = true; }

        uint256 limitAfterZero = c.getAssetCurrentLimit(asset);

        bool overReverted;
        try c.depositAsset(asset, limitBefore + 1) { overReverted = false; } catch { overReverted = true; }

        uint256 limitAfterOver = c.getAssetCurrentLimit(asset);

        uint256 minted = c.getRsETHAmountToMint(asset, limitBefore);
        bool atLimitSucceeded;
        try c.depositAsset(asset, limitBefore) { atLimitSucceeded = true; } catch { atLimitSucceeded = false; }

        uint256 limitAfterSuccess = c.getAssetCurrentLimit(asset);

        assert(zeroReverted && overReverted && atLimitSucceeded && minted > 0 && limitAfterZero == limitBefore && limitAfterOver == limitBefore && limitAfterSuccess == 0);
    }

    receive() external payable {}
}

