contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        // Only exercise the deposit path with a plausible deposit.
        require(asset != address(0));
        require(depositAmount > 0);

        uint256 beforeAssetBalance = IERC20(asset).balanceOf(address(this));
        uint256 beforeRsethSupply = IERC20(c.lrtConfig()).totalSupply();

        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAssetBalance = IERC20(asset).balanceOf(address(this));
        uint256 afterRsethSupply = IERC20(c.lrtConfig()).totalSupply();

        // A successful deposit must have moved exactly depositAmount of asset
        // from this test contract into c and caused rsETH to be minted.
        if (!reverted) {
            assert(
                beforeAssetBalance >= afterAssetBalance &&
                beforeAssetBalance - afterAssetBalance == depositAmount &&
                afterRsethSupply > beforeRsethSupply
            );
        } else {
            // A rejected deposit must not leave the test contract poorer in asset.
            assert(beforeAssetBalance == afterAssetBalance);
        }
    }
}

