contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0), "asset zero");

        // Setup: pause and unpause is admin-only; since this contract is the deployer, it can unpause if needed.
        // But we rely on the contract being unpaused initially in a fresh deployment.

        // Capture pre-call observable state
        address lrtConfigAddr = address(c.lrtConfig());
        bool beforePaused = c.paused();
        uint256 beforeAssetBalance = IERC20(asset).balanceOf(address(c));

        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: depositAsset must revert for zero depositAmount (InvalidAmount check is after mint but before transfer)
        // Also if it does not revert, the contract's paused state must remain unchanged and its asset balance must increase
        // by exactly depositAmount (assuming the caller has approved and holds enough, but our test contract is the caller
        // and it cannot hold tokens unless we set that up; however, for a general rule we condition on non-revert success).
        // We assert: if depositAmount == 0, it must revert. If it does not revert, paused state unchanged and
        // asset balance increases by depositAmount.
        assert(
            (depositAmount == 0 && reverted) ||
            (!reverted && c.paused() == beforePaused && IERC20(asset).balanceOf(address(c)) == beforeAssetBalance + depositAmount)
        );
    }

    receive() external payable {}
}

