contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        // Precondition: use a parameterized nonzero address, and avoid huge amounts.
        require(asset != address(0));

        // Setup must be top-level calls on c. Fresh c may not be initialized yet.
        c.initialize(address(this));

        // Read the public configuration getters before the deciding call.
        bool supported = c.lrtConfig().isSupportedAsset(asset);
        uint256 totalBefore = supported ? c.getTotalAssetDeposits(asset) : 0;

        // Make the deciding call. For zero amount, it must revert with InvalidAmount before any transfer/mint.
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (depositAmount == 0) {
            // General rule: a zero deposit is always invalid.
            assert(reverted);
        } else if (supported) {
            // General rule: if no revert occurs, the deposit did not exceed the current limit
            // and the deposit increased the recorded total asset deposits.
            if (!reverted) {
                assert(c.getTotalAssetDeposits(asset) >= totalBefore);
            }
        } else {
            // Unsupported assets are rejected by onlySupportedAsset.
            assert(reverted);
        }
    }

    receive() external payable {}
}

