contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 ndcIndex) public payable {
        bool reverted;
        uint256 total;
        uint256 sum;

        address[] memory queue = c.getNodeDelegatorQueue();
        if (queue.length > 0) {
            if (ndcIndex >= queue.length) {
                ndcIndex = queue.length - 1;
            }
        }

        try c.getTotalAssetDeposits(asset) returns (uint256 v) {
            reverted = false;
            total = v;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            sum = _expectedTotal(asset, queue);
        }

        assert(reverted || total == sum);
    }

    function _expectedTotal(address asset, address[] memory queue) private view returns (uint256 sum) {
        sum = _balanceOf(asset, address(c));
        for (uint256 i = 0; i < queue.length; ++i) {
            sum += _balanceOf(asset, queue[i]);
            sum += _assetBalance(queue[i], asset);
        }
    }

    function _balanceOf(address token, address account) private view returns (uint256) {
        (bool ok, bytes memory data) = token.staticcall(
            abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), account)
        );
        if (ok && data.length >= 32) {
            return abi.decode(data, (uint256));
        }
        return 0;
    }

    function _assetBalance(address ndc, address asset) private view returns (uint256) {
        (bool ok, bytes memory data) = ndc.staticcall(
            abi.encodeWithSelector(bytes4(keccak256("getAssetBalance(address)")), asset)
        );
        if (ok && data.length >= 32) {
            return abi.decode(data, (uint256));
        }
        return 0;
    }

    receive() external payable {}
}

