contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address lrtConfigAddr, address asset, uint256 depositAmount) public payable {
        require(lrtConfigAddr != address(0), "config zero");
        require(asset != address(0), "asset zero");

        // Re-deploying c is not allowed, but its state can be mutated only by calls to c itself.
        // We rely on the deployment harness: c is fresh, so initialize it.
        c.initialize(lrtConfigAddr);

        // Snapshot the pool's balance of the asset before any deposit.
        uint256 balanceBefore = IERC20(asset).balanceOf(address(c));

        // Attempt the deposit; do not revert the test if the contract rejects it.
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Snapshot after the call.
        uint256 balanceAfter = IERC20(asset).balanceOf(address(c));

        // General rule: either the deposit was rejected (reverted), or the pool's
        // balance of the asset increased by exactly the requested deposit amount.
        // Zero-amount deposits are separately expected to revert (as they are invalid), but
        // the rule is stated as: if it did not revert, the increase equals depositAmount.
        assert(reverted || balanceAfter == balanceBefore + depositAmount);
    }

    receive() external payable {}
}

