contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        require(address(c) != address(0), "no pool");
        address thisAddr = address(this);

        // We can only deposit if the config is initialized and the asset is supported.
        address lrtConfigAddr = address(c.lrtConfig());
        require(lrtConfigAddr != address(0), "lrtConfig not set");
        require(ILRTConfig(lrtConfigAddr).isSupportedAsset(asset), "asset not supported");

        // The pool must be unpaused and the deposit must pass the pool's own checks.
        require(!c.paused(), "pool paused");
        require(depositAmount != 0, "zero deposit");
        require(depositAmount <= c.getAssetCurrentLimit(asset), "deposit over limit");

        // We must hold enough of the asset and approve the pool to pull it.
        // Use the asset parameter as an ERC20; this is an external call on the asset, not on c.
        IERC20 token = IERC20(asset);
        require(token.balanceOf(thisAddr) >= depositAmount, "insufficient asset balance");
        token.approve(address(c), depositAmount);

        // Expected rsETH minted, read from the pool before the deposit changes state.
        uint256 expectedMint = c.getRsETHAmountToMint(asset, depositAmount);

        // Depositor's rsETH balance before.
        address rsethTokenAddr = c.lrtConfig().rsETH();
        uint256 rsethBefore = IERC20(rsethTokenAddr).balanceOf(thisAddr);

        c.depositAsset(asset, depositAmount);

        uint256 rsethAfter = IERC20(rsethTokenAddr).balanceOf(thisAddr);

        assert(rsethAfter == rsethBefore + expectedMint);
    }

    receive() external payable {}
}

